export async function checkIndicSelection(source,out){
 const pdfjs=await import('pdfjs-dist/legacy/build/pdf.mjs'),{createCanvas}=await import('@napi-rs/canvas');
 const a=await pdfjs.getDocument({data:new Uint8Array(source)}).promise,b=await pdfjs.getDocument({data:new Uint8Array(out)}).promise;
 try{const p=await b.getPage(1),items=(await p.getTextContent()).items.filter(i=>i.str.trim());
  assert.equal(items.length,16,'Every positioned Indic word stays distinct');
  for(const [n,it]of items.entries()){const i=Math.floor(n/2),j=n%2;assert.equal(it.str,INDIC_WORDS[i],'Exact Unicode word');assert.ok(Math.abs(it.width-[60,120][j])<.01,'Indic selection must cover its whole word box: '+it.str+' '+it.width);assert.ok(Math.abs(it.transform[4]-(35+j*185))<.01);assert.ok(Math.abs(it.transform[5]-(720-(55+i*75+26)))<.01);}
  const render=async(page)=>{const v=page.getViewport({scale:1}),c=createCanvas(v.width,v.height);await page.render({canvasContext:c.getContext('2d'),viewport:v}).promise;return c.getContext('2d').getImageData(0,0,c.width,c.height).data;};
  assert.deepEqual(await render(await a.getPage(1)),await render(p),'Invisible font must not change any painted pixels');
 }finally{await a.destroy();await b.destroy();}
}
